import type { ProcedureProfile, Source } from "./types";

/**
 * Procedure decision files.
 *
 * Every profile separates the treatment purpose, the strength of evidence for
 * that purpose, what a published cost figure does and does not include, the
 * recovery timeline, common and serious risks, who should pause, who performs
 * it in the United States, and the U.S. regulatory status of what is used.
 *
 * Cost figures: the American Society of Plastic Surgeons publishes national
 * average physician fees on its procedure cost pages and labels them "the
 * latest statistics" without stating the survey year. Its 2025 statistics
 * report no longer publishes minimally invasive procedure counts or fees
 * (ASPS says it is seeking a new data source), so where no current figure is
 * published the profile says so instead of guessing.
 *
 * Reviewed dates are per profile. A material status change gets a dated entry
 * in `updates`, never a silent rewrite.
 */

